ee:variables.ee:set-variable:
%dw 2.0
import take from dw::core::Arrays
output application/java

var severityRank = { on_track: 0, insufficient_data: 1, soft_warning: 2, hard_flag: 3 }
var severityScore = { soft_warning: 10, hard_flag: 20 }
var tiePriority = { micronutrients: 0, macros: 1, calories: 2, sleep: 3, recovery: 4, activity: 5 }

fun isFlagged(status) = status == "soft_warning" or status == "hard_flag"

fun candidate(dimension, nutrient, block) = {
    dimension: dimension,
    nutrient: nutrient,
    severity: block.status,
    condition_context: block.condition_context
}

// Worst item by severity, then condition context, then list order (earlier wins).
// Subtracting the index makes every key unique, so there are no ties to break.
fun worstOf(items) =
    if (isEmpty(items)) null
    else (items orderBy ((item, index) ->
        (severityRank[item.entry.status] default 0) * 100
        + (if (item.entry.condition_context != null) 10 else 0)
        - index))[-1]

fun gatherCandidates(response) = do {
    var trends = response.dimension_trends
    var macroItems = [
        { name: "protein", entry: trends.macros.protein },
        { name: "carbohydrates", entry: trends.macros.carbohydrates },
        { name: "fat", entry: trends.macros.fat },
        { name: "saturated_fat", entry: trends.macros.saturated_fat },
        { name: "fiber", entry: trends.macros.fiber },
        { name: "sodium", entry: trends.macros.sodium }
    ]
    var microItems = (trends.micronutrients default []) map ((n) -> { name: n.nutrient, entry: n })
    var worstMacro = worstOf(macroItems)
    var worstMicro = worstOf(microItems)
    ---
    [
        if (isFlagged(worstMicro.entry.status)) candidate("micronutrients", worstMicro.name, worstMicro.entry) else null,
        if (isFlagged(worstMacro.entry.status)) candidate("macros", worstMacro.name, worstMacro.entry) else null,
        if (isFlagged(trends.calories.status)) candidate("calories", null, trends.calories) else null,
        if (isFlagged(trends.sleep.status)) candidate("sleep", null, trends.sleep) else null,
        if (isFlagged(trends.recovery.status)) candidate("recovery", null, trends.recovery) else null,
        if (isFlagged(trends.activity.status)) candidate("activity", null, trends.activity) else null
    ] filter ((c) -> c != null)
}

fun score(c) =
    (severityScore[c.severity] default 0) + (if (c.condition_context != null) 1 else 0)

// Highest score first. Within a score, the lower tiePriority number comes first.
// The tie priority is at most 5 and the score is multiplied by 10, so it can
// never override severity or condition context.
fun rankCandidates(candidates) =
    candidates orderBy ((c) -> -(score(c) * 10 - (tiePriority[c.dimension] default 9)))

fun buildRecommendations(candidates) =
    take(rankCandidates(candidates), 3) map ((c, index) ->
        { rank: index + 1 } ++ c ++ { text: null })
---
buildRecommendations(gatherCandidates(vars.evalResponse))

ee:message.ee:set-payload:
%dw 2.0 output application/json
fun cleanMacros(block) = block mapObject ((value, key) -> if (value is Object) { (key): value - "condition_context" } else { (key): value })
fun cleanTrends(trends) = trends mapObject ((value, key) -> if ((key as String) == "macros") { (key): cleanMacros(value) } else { (key): value }) var days = vars.window.value as Number var start = vars.window.start as Date var end = start + ("P$(days - 1)D" as Period) --- { user_id: vars.userId, window_days: days, window_start: start, window_end: end, generated_at: now(), generation_mode: vars.textMode, threshold_version: "", coverage: vars.evalResponse.coverage, dimension_trends: cleanTrends(vars.evalResponse.dimension_trends), recommendations: vars.addText default [], pattern_signals: vars.patternSignals default [], metrics_shown : (vars.userProfile.preferences.preferredWearableMetrics default []) ++ (vars.userProfile.preferences.preferredNutritionMetrics default []) }
